//#region src/utils/precompressed-variant.ts
const RESPONSE_HEADER_OVERHEAD = {
	br: 45,
	gzip: 47,
	zstd: 47
};
/**
* Return whether an encoded representation reduces conservative HTTP/1 wire
* bytes after accounting for the response fields needed to negotiate it.
*/
function isPrecompressedVariantBeneficial(compressedSize, originalSize, encoding) {
	return originalSize - compressedSize > RESPONSE_HEADER_OVERHEAD[encoding];
}
//#endregion
export { isPrecompressedVariantBeneficial };
